def hidden_rule_fn(state):
    """
    Rule:
    1. For each particle, find other-type particles with pairwise splurn = 0.
    2. If match exists, move TOWARD the closest matching other-type particle.
    3. If no match:
       - BLINX: move AWAY from closest other-type particle.
       - TORVE: STAY.
    4. Resolve collisions: if two particles want the same destination, TORVE stays.
    """
    n = len(state)

    def splurn(x1, y1, x2, y2):
        return (x1 + y1 + x2 + y2) % 2

    def wrap_diff(a, b):
        """Compute shortest path from a to b on 8x8 toroidal grid."""
        d = (b - a) % 8
        if d > 4:
            d = d - 8
        return d

    def chebyshev(x1, y1, x2, y2):
        dx = abs(wrap_diff(x1, x2))
        dy = abs(wrap_diff(y1, y2))
        return max(dx, dy)

    # Compute desired destination for each particle
    destinations = [None] * n
    for i in range(n):
        p = state[i]
        px, py, pt = p['x'], p['y'], p['type']

        # Find other-type particles with pairwise splurn = 0
        matches = []
        for j in range(n):
            if i == j:
                continue
            q = state[j]
            if q['type'] != pt:
                if splurn(px, py, q['x'], q['y']) == 0:
                    dist = chebyshev(px, py, q['x'], q['y'])
                    matches.append((dist, q['x'], q['y']))

        if matches:
            # Sort by distance, then by x, then by y for tie-breaking
            matches.sort()
            _, tx, ty = matches[0]
            dx = wrap_diff(px, tx)
            dy = wrap_diff(py, ty)
            # Normalize to {-1, 0, 1}
            dx = 1 if dx > 0 else (-1 if dx < 0 else 0)
            dy = 1 if dy > 0 else (-1 if dy < 0 else 0)
            destinations[i] = ((px + dx) % 8, (py + dy) % 8)
        else:
            # No match: find closest other-type particle
            others = []
            for j in range(n):
                if i == j:
                    continue
                q = state[j]
                if q['type'] != pt:
                    dist = chebyshev(px, py, q['x'], q['y'])
                    others.append((dist, q['x'], q['y']))

            others.sort()
            _, tx, ty = others[0]

            if pt == 'BLINX':
                # Move AWAY from closest other-type
                dx = wrap_diff(tx, px)  # opposite direction
                dy = wrap_diff(ty, py)
                dx = 1 if dx > 0 else (-1 if dx < 0 else 0)
                dy = 1 if dy > 0 else (-1 if dy < 0 else 0)
                destinations[i] = ((px + dx) % 8, (py + dy) % 8)
            else:
                # TORVE: stay
                destinations[i] = (px, py)

    # Resolve collisions: if two particles want the same cell, TORVE stays
    cell_to_particles = {}
    for i in range(n):
        dest = destinations[i]
        if dest not in cell_to_particles:
            cell_to_particles[dest] = []
        cell_to_particles[dest].append(i)

    final_state = [None] * n
    for dest, indices in cell_to_particles.items():
        if len(indices) > 1:
            # Collision: keep BLINX, TORVE stays at original position
            blinx_indices = [i for i in indices if state[i]['type'] == 'BLINX']
            torve_indices = [i for i in indices if state[i]['type'] == 'TORVE']
            if blinx_indices:
                for i in blinx_indices:
                    final_state[i] = {'type': state[i]['type'], 'x': dest[0], 'y': dest[1]}
            for i in torve_indices:
                final_state[i] = {'type': state[i]['type'], 'x': state[i]['x'], 'y': state[i]['y']}
        else:
            i = indices[0]
            final_state[i] = {'type': state[i]['type'], 'x': dest[0], 'y': dest[1]}

    return final_state
